.photo-question {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}

.photo-question__idle {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.85rem;
  padding: 1.5rem 1rem;
  text-align: center;
  width: 100%;
}

.photo-question__question {
  margin: 0;
  font-weight: 700;
  font-size: 1.05rem;
  color: var(--farm-text-dark);
}

.photo-question__hint {
  margin: 0;
  font-size: 0.85rem;
  color: var(--farm-text-muted);
}

.photo-question__offline-note {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  margin: 0;
  font-size: 0.78rem;
  color: var(--farm-wood-dark);
  background: var(--farm-cream-dark);
  border-radius: 999px;
  padding: 0.35rem 0.75rem;
}

.photo-question__camera,
.photo-question__preview {
  width: 100%;
  display: flex;
  justify-content: center;
  padding: 0.5rem 0;
}

.photo-question__confirmed {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  padding: 1.5rem 1rem;
  text-align: center;
}

.photo-question__confirmed-icon {
  width: 2.5rem;
  height: 2.5rem;
  color: var(--farm-accent-dark);
}

.photo-question__confirmed-title {
  margin: 0;
  font-weight: 800;
  font-size: 1.1rem;
  color: var(--farm-text-dark);
}

.photo-question__confirmed-note {
  margin: 0;
  font-size: 0.82rem;
  color: var(--farm-text-muted);
}

.photo-question__confirmed-thumb {
  width: 100%;
  max-width: 220px;
  border-radius: 0.75rem;
  border: 2px solid var(--farm-wood);
  margin: 0.5rem 0;
}

.photo-question__error {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  padding: 2rem 1rem;
  color: var(--farm-wood-dark);
  text-align: center;
}
